<div class="reseller-shell reseller-portal"><div class="container"><div class="reseller-page-toolbar"><div><span class="reseller-kicker">Nota baru</span><h1>Susun penawaran customer</h1><p>Harga jual minimal sama dengan harga dasar dan tidak akan ditampilkan kepada admin sebagai harga customer.</p></div><a href="<?= base_url('reseller/quotes') ?>" class="btn-reseller-secondary">Batal</a></div><?php if ($errors = session()->getFlashdata('errors')): ?><div class="reseller-alert danger"><?php foreach ((array) $errors as $error): ?><p><?= esc($error) ?></p><?php endforeach; ?></div><?php endif; ?><?php if ($error = session()->getFlashdata('error')): ?><div class="reseller-alert danger"><p><?= esc($error) ?></p></div><?php endif; ?><?php if (!$products): ?><div class="reseller-empty"><i class="fas fa-box-open"></i><h2>Belum ada produk berharga</h2><p>Hubungi admin agar produk dan harga dasar diterbitkan.</p></div><?php else: ?><form action="<?= base_url('reseller/quotes') ?>" method="post" id="quote-form" class="quote-form-card"><?= csrf_field() ?><div class="reseller-form-grid"><div class="reseller-field"><label for="customer_name">Nama customer</label><input id="customer_name" name="customer_name" value="<?= esc(old('customer_name')) ?>" required></div><div class="reseller-field"><label for="customer_phone">WhatsApp customer</label><input id="customer_phone" name="customer_phone" value="<?= esc(old('customer_phone')) ?>"></div><div class="reseller-field full"><label for="customer_address">Alamat</label><textarea id="customer_address" name="customer_address" rows="2"><?= esc(old('customer_address')) ?></textarea></div></div><div class="quote-items-head"><div><span>Item nota</span><h2>Produk dan harga jual</h2></div><button type="button" id="add-quote-item" class="btn-reseller-secondary"><i class="fas fa-plus"></i> Tambah Item</button></div><div id="quote-items"><div class="quote-item-row"><button type="button" class="quote-remove" aria-label="Hapus item"><i class="fas fa-xmark"></i></button><div class="reseller-field quote-product"><label>Produk</label><select name="product_id[]" required><option value="">Pilih produk</option><?php foreach ($products as $product): ?><option value="<?= $product['id'] ?>" data-base="<?= (float) $product['base_price'] ?>" data-min="<?= (int) $product['min_order'] ?>" data-colors="<?= esc($product['available_colors'], 'attr') ?>" data-sizes="<?= esc($product['available_sizes'], 'attr') ?>"><?= esc($product['sku'] . ' — ' . $product['nama']) ?></option><?php endforeach; ?></select><small class="quote-base">Pilih produk untuk melihat harga dasar.</small></div><div class="reseller-field"><label>Warna</label><input name="color[]" placeholder="Pilih sesuai katalog"></div><div class="reseller-field"><label>Ukuran</label><input name="size[]" placeholder="Contoh: L"></div><div class="reseller-field"><label>Jumlah</label><input type="number" name="quantity[]" min="1" value="1" required></div><div class="reseller-field"><label>Harga jual / pcs</label><input type="number" name="selling_price[]" min="0" step="1000" required></div></div></div><div class="reseller-field"><label for="quote_notes">Catatan nota</label><textarea id="quote_notes" name="notes" rows="3"><?= esc(old('notes')) ?></textarea></div><button class="btn-reseller-primary reseller-submit" type="submit">Simpan Nota <i class="fas fa-arrow-right"></i></button></form><template id="quote-item-template"><div class="quote-item-row"><button type="button" class="quote-remove" aria-label="Hapus item"><i class="fas fa-xmark"></i></button><div class="reseller-field quote-product"><label>Produk</label><select name="product_id[]" required><option value="">Pilih produk</option><?php foreach ($products as $product): ?><option value="<?= $product['id'] ?>" data-base="<?= (float) $product['base_price'] ?>" data-min="<?= (int) $product['min_order'] ?>" data-colors="<?= esc($product['available_colors'], 'attr') ?>" data-sizes="<?= esc($product['available_sizes'], 'attr') ?>"><?= esc($product['sku'] . ' — ' . $product['nama']) ?></option><?php endforeach; ?></select><small class="quote-base">Pilih produk untuk melihat harga dasar.</small></div><div class="reseller-field"><label>Warna</label><input name="color[]"></div><div class="reseller-field"><label>Ukuran</label><input name="size[]"></div><div class="reseller-field"><label>Jumlah</label><input type="number" name="quantity[]" min="1" value="1" required></div><div class="reseller-field"><label>Harga jual / pcs</label><input type="number" name="selling_price[]" min="0" step="1000" required></div></div></template><script src="<?= base_url('assets/js/reseller-quote.js') ?>"></script><?php endif; ?></div></div>
